ion_r778446979"},"pull_request":{"href":"https://api.github.com/repos/numpy/numpy/pulls/20722"}},"reactions":{"url":"https://api.github.com/repos/numpy/numpy/pulls/comments/778446979/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":null,"original_start_line":null,"start_side":null,"line":534,"original_line":534,"side":"RIGHT","in_reply_to_id":777861843},"pull_request":{"url":"https://api.github.com/repos/numpy/numpy/pulls/20722","id":813613239,"node_id":"PR_kwDOAA3dP84wfsC3","html_url":"https://github.com/numpy/numpy/pull/20722","diff_url":"https://github.com/numpy/numpy/pull/20722.diff","patch_url":"https://github.com/numpy/numpy/pull/20722.patch","issue_url":"https://api.github.com/repos/numpy/numpy/issues/20722","number":20722,"state":"open","locked":false,"title":"ENH: Added ability to change dtype of view when last axis has shape 1","user":{"login":"madphysicist","id":4617010,"node_id":"MDQ6VXNlcjQ2MTcwMTA=","avatar_url":"https://avatars.githubusercontent.com/u/4617010?v=4","gravatar_id":"","url":"https://api.github.com/users/madphysicist","html_url":"https://github.com/madphysicist","followers_url":"https://api.github.com/users/madphysicist/followers","following_url":"https://api.github.com/users/madphysicist/following{/other_user}","gists_url":"https://api.github.com/users/madphysicist/gists{/gist_id}","starred_url":"https://api.github.com/users/madphysicist/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/madphysicist/subscriptions","organizations_url":"https://api.github.com/users/madphysicist/orgs","repos_url":"https://api.github.com/users/madphysicist/repos","events_url":"https://api.github.com/users/madphysicist/events{/privacy}","received_events_url":"https://api.github.com/users/madphysicist/received_events","type":"User","site_admin":false},"body":"This is a first attempt to fix some of #20705. In this PR, I attempt to make the following two changes to `np.ndarray.view`:

1. If `dtype` is smaller than the current dtype, and it divides the current one evenly, and there is at least one unit dimension, expand the last unit dimension instead of crashing.
2. If `dtype` is larger than the current dtype, and there exists an axis along which the current array is contiguous (stride == current dtype.itemsize), use that axis instead of crashing.

Both cases are valid because the check for dtype multiplicative compatibility is still done, and the dimension/stride checks guarantee that the resulting shape changes do not exceed known owned memory.

